#!/usr/bin/env python3
import sys
import os
import re
import math
import random
import struct
import unicodedata
from decimal import Decimal, InvalidOperation
from functools import cmp_to_key

VERSION = "0.13.0"
COMMANDS = ["cat", "count", "fixlengths", "flatten", "fmt", "frequency", "headers", "help", "index", "input", "join", "partition", "reverse", "sample", "search", "select", "slice", "sort", "split", "stats", "table"]
# commands in docopt variant order (observed in error message)
VARIANT_COMMANDS = ["cat", "count", "fixlengths", "flatten", "fmt", "frequency", "headers", "help", "index", "input", "join", "partition", "reverse", "sample", "search", "select", "slice", "sort", "split", "stats", "table"]

class CliError(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg

class UsageError(CliError):
    def __init__(self, msg, usage):
        super().__init__(msg)
        self.usage = usage

class HelpExit(Exception):
    def __init__(self, text):
        self.text = text

def _enc(s):
    if isinstance(s, bytes):
        return s
    return os.fsencode(str(s))

def out_bytes(b):
    try:
        sys.stdout.buffer.write(b)
    except BrokenPipeError:
        raise CliError("Broken pipe (os error 32)")

def err_bytes(b):
    try:
        sys.stderr.buffer.write(b)
    except BrokenPipeError:
        pass

def io_error_str(e):
    # e is OSError
    strerror = e.strerror or str(e)
    # Python's strerror matches C strerror used by Rust for these cases.
    return f"{strerror} (os error {e.errno})"

def raise_io(e):
    raise CliError(io_error_str(e))

def rust_lower(s):
    return s.lower()

def levenshtein(a, b):
    if a == b:
        return 0
    la, lb = len(a), len(b)
    if la == 0:
        return lb
    if lb == 0:
        return la
    prev = list(range(lb + 1))
    cur = [0] * (lb + 1)
    for i in range(1, la + 1):
        cur[0] = i
        ai = a[i-1]
        for j in range(1, lb + 1):
            cost = 0 if ai == b[j-1] else 1
            cur[j] = min(prev[j] + 1, cur[j-1] + 1, prev[j-1] + cost)
        prev, cur = cur, prev
    return prev[lb]

PYEOF
