class OptSpec:
    __slots__ = ("short", "long", "has_value", "default", "kind", "display")
    def __init__(self, short, long, has_value=False, default=None, kind='string', display=None):
        self.short = short
        self.long = long
        self.has_value = has_value
        self.default = default
        self.kind = kind
        self.display = display if display is not None else ('--' + long if long else '-' + (short or ''))
    @property
    def key(self):
        return self.long.replace('-', '_') if self.long else self.short

class CmdSpec:
    def __init__(self, name, options, pos_min, pos_max, pos_names=None, pos_kinds=None, literals=None, help_alt=False, decode_order=None):
        self.name = name
        self.options = options
        self.pos_min = pos_min
        self.pos_max = pos_max  # None = unlimited
        self.pos_names = pos_names or []
        # pos_kinds: list parallel-ish for numeric/select positionals: dict index->(kind, display)
        self.pos_kinds = pos_kinds or {}
        self.literals = literals  # for cat: first positional must be in set
        self.help_alt = help_alt
        self.decode_order = decode_order or []
        # maps
        self.by_long = {}
        self.by_short = {}
        for o in options:
            if o.long:
                self.by_long[o.long] = o
            if o.short:
                self.by_short[o.short] = o

def usage_segment(help_text):
    # Extract "Usage:\n..." up to blank line
    idx = help_text.find("Usage:\n")
    if idx == -1:
        return help_text
    rest = help_text[idx:]
    end = rest.find("\n\n")
    if end == -1:
        seg = rest.rstrip("\n")
    else:
        seg = rest[:end]
    return seg + "\n"

def parse_single_ascii(s):
    if s == "\\t":
        return 9
    b = _enc(s)
    if len(b) == 1 and b[0] < 128:
        return b[0]
    raise CliError(f"Could not convert '{s}' to a single ASCII character.")

def parse_u64_docopt(s, display):
    if s == "":
        return 0
    v = parse_rust_usize(s)
    if v is None:
        raise CliError(f"Could not deserialize '{s}' to u64 for '{display}'.")
    return v

def docopt_parse(spec, argv):
    """Returns (values dict, positionals list). values include converted types.
    Raises UsageError / HelpExit / CliError (for deserialize)."""
    help_text = HELPS.get(spec.name, "")
    usage = usage_segment(help_text)
    raw_flags = {}  # key -> raw string value or True
    counts = {}
    positionals = []
    i = 0
    end_of_opts = False
    n = len(argv)
    long_candidates = ['--' + o.long for o in spec.options if o.long]
    while i < n:
        tok = argv[i]
        if not end_of_opts and tok == "--":
            end_of_opts = True
            i += 1
            continue
        if not end_of_opts and tok.startswith("--") and tok != "--":
            if "=" in tok:
                name, eqval = tok.split("=", 1)
                has_eq = True
            else:
                name, eqval = tok, None
                has_eq = False
            long_name = name[2:]
            opt = spec.by_long.get(long_name)
            if opt is None:
                # unknown flag; name displayed includes leading -- (and extra - etc)
                disp = name
                # did you mean?
                best = None
                bestdist = 3
                for cand in long_candidates:
                    d = levenshtein(disp, cand)
                    if d < bestdist:
                        bestdist = d
                        best = cand
                if best is not None:
                    raise UsageError(f"Unknown flag: '{disp}'. Did you mean '{best}'?", usage)
                else:
                    raise UsageError(f"Unknown flag: '{disp}'", usage)
            if not opt.has_value:
                if has_eq:
                    raise UsageError(f"Flag '--{opt.long}' cannot have an argument, but found '{eqval}'.", usage)
                counts[opt.key] = counts.get(opt.key, 0) + 1
                raw_flags[opt.key] = True
                i += 1
                continue
            else:
                counts[opt.key] = counts.get(opt.key, 0) + 1
                if has_eq:
                    raw_flags[opt.key] = eqval
                    i += 1
                    continue
                else:
                    if i + 1 >= n:
                        raise UsageError(f"Expected argument for flag '--{opt.long}' but reached end of arguments.", usage)
                    raw_flags[opt.key] = argv[i+1]
                    i += 2
                    continue
        elif not end_of_opts and tok.startswith("-") and tok != "-":
            # short bundle
            chars = tok[1:]
            j = 0
            consumed_next = False
            while j < len(chars):
                c = chars[j]
                opt = spec.by_short.get(c)
                if opt is None:
                    raise UsageError(f"Unknown flag: '-{c}'", usage)
                if not opt.has_value:
                    counts[opt.key] = counts.get(opt.key, 0) + 1
                    raw_flags[opt.key] = True
                    j += 1
                    continue
                else:
                    counts[opt.key] = counts.get(opt.key, 0) + 1
                    rest = chars[j+1:]
                    if rest != "":
                        raw_flags[opt.key] = rest
                    else:
                        if i + 1 >= n:
                            raise UsageError(f"Expected argument for flag '--{opt.long}' but reached end of arguments.", usage)
                        raw_flags[opt.key] = argv[i+1]
                        consumed_next = True
                    j = len(chars)
                    break
            i += 2 if consumed_next else 1
            continue
        else:
            positionals.append(tok)
            i += 1
            continue
    # pattern validation
    has_help = counts.get('help', 0) > 0
    dup = any(v > 1 for v in counts.values())
    # positional validation
    def pos_ok():
        if spec.literals is not None:
            if len(positionals) < 1:
                return False
            if positionals[0] not in spec.literals:
                return False
            # remaining unlimited (pos_max applies to remaining? for cat unlimited)
            return True
        if len(positionals) < spec.pos_min:
            return False
        if spec.pos_max is not None and len(positionals) > spec.pos_max:
            return False
        return True
    valid = (not dup) and pos_ok()
    if not valid:
        # help alternative pattern: only --help flag, no positionals, no other flags
        if spec.help_alt and has_help and not dup and len(positionals) == 0 and len(counts) == 1:
            raise HelpExit(help_text)
        raise UsageError("Invalid arguments.", usage)
    if has_help:
        raise HelpExit(help_text)
    # deserialize / convert in decode_order
    values = {}
    # defaults for bool flags
    for o in spec.options:
        if not o.has_value:
            values[o.key] = bool(raw_flags.get(o.key, False))
    # We'll fill value flags and positionals according to decode_order if provided,
    # otherwise in options order then positionals.
    def convert_flag(o):
        if o.key in values and not o.has_value:
            return
        if o.key in raw_flags:
            raw = raw_flags[o.key]
        elif o.default is not None:
            raw = o.default
        else:
            values[o.key] = None
            return
        if o.kind == 'u64':
            values[o.key] = parse_u64_docopt(raw, o.display)
        elif o.kind == 'single':
            values[o.key] = parse_single_ascii(raw)
        elif o.kind == 'select':
            values[o.key] = parse_select_columns(raw)
        else:
            values[o.key] = raw
    def convert_pos(idx):
        # pos_kinds may define kind
        kind_info = spec.pos_kinds.get(idx)
        if idx >= len(positionals):
            return None
        raw = positionals[idx]
        if kind_info is not None:
            kind, display = kind_info
            if kind == 'u64':
                return parse_u64_docopt(raw, display)
            elif kind == 'select':
                return parse_select_columns(raw)
            else:
                return raw
        return raw
    # decode_order items: ('flag', key) or ('pos', idx)
    converted_pos = {}
    if spec.decode_order:
        for typ, ident in spec.decode_order:
            if typ == 'flag':
                o = None
                for oo in spec.options:
                    if oo.key == ident:
                        o = oo
                        break
                if o is not None and o.has_value:
                    convert_flag(o)
            elif typ == 'pos':
                converted_pos[ident] = convert_pos(ident)
        # convert any remaining flags
        for o in spec.options:
            if o.has_value and o.key not in values:
                convert_flag(o)
        for idx in range(len(positionals)):
            if idx not in converted_pos:
                converted_pos[idx] = convert_pos(idx)
    else:
        for o in spec.options:
            if o.has_value:
                convert_flag(o)
        for idx in range(len(positionals)):
            converted_pos[idx] = convert_pos(idx)
    # Attach converted positionals by name if provided
    pos_values = []
    for idx in range(len(positionals)):
        v = converted_pos.get(idx, positionals[idx])
        pos_values.append(v)
    return values, pos_values, positionals

