# ------------------------- Selection parsing -------------------------

def parse_rust_usize(s):
    """Return int if s parses as Rust usize (u64), else None."""
    if s == "":
        return None
    t = s
    if t[0] == '+':
        t = t[1:]
        if t == "":
            return None
    if not t.isascii() or not t.isdigit():
        return None
    try:
        v = int(t)
    except ValueError:
        return None
    if v > 18446744073709551615:
        return None
    return v

def rust_parse_int_error(s):
    """Error message suffix for Rust parse::<usize>() failures."""
    if s == "":
        return "cannot parse integer from empty string"
    t = s[1:] if s.startswith('+') else s
    if t != "" and t.isascii() and t.isdigit():
        # must be overflow
        return "number too large to fit in target type"
    return "invalid digit found in string"

def parse_bracket_int(s):
    v = parse_rust_usize(s)
    if v is None:
        raise CliError(f"Could not convert '{s}' to an integer: {rust_parse_int_error(s)}")
    return v

class OneSelector:
    __slots__ = ("kind", "name", "dup", "index")
    def __init__(self, kind, name=None, dup=0, index=None):
        self.kind = kind  # 'name' or 'index'
        self.name = name
        self.dup = dup
        self.index = index

class Selector:
    __slots__ = ("kind", "one", "start", "end")
    def __init__(self, kind, one=None, start=None, end=None):
        self.kind = kind  # 'one' or 'range'
        self.one = one
        self.start = start
        self.end = end

class SelectColumns:
    __slots__ = ("selectors", "invert")
    def __init__(self, selectors, invert):
        self.selectors = selectors
        self.invert = invert

def _make_one(name, dup):
    if dup is None:
        v = parse_rust_usize(name)
        if v is not None:
            return OneSelector('index', index=v)
    return OneSelector('name', name=name, dup=0 if dup is None else dup)

def parse_select_columns(spec):
    if spec is None:
        return None
    s = spec
    n = len(s)
    pos = 0
    invert = False
    if pos < n and s[pos] == '!':
        invert = True
        pos += 1
    selectors = []

    def parse_one_opt():
        nonlocal pos
        if pos >= n or s[pos] in ',-':
            return None
        dup = None
        if s[pos] == '"':
            pos += 1
            chars = []
            closed = False
            while pos < n:
                ch = s[pos]
                if ch == '"':
                    if pos + 1 < n and s[pos+1] == '"':
                        chars.append('""')
                        pos += 2
                        continue
                    else:
                        pos += 1
                        closed = True
                        break
                else:
                    chars.append(ch)
                    pos += 1
            if not closed:
                raise CliError('Unclosed quote, missing closing ".')
            name = ''.join(chars)
        else:
            start = pos
            while pos < n and s[pos] not in ',[-':
                pos += 1
            name = s[start:pos]
        if pos < n and s[pos] == '[':
            pos += 1
            start = pos
            while pos < n and s[pos] != ']':
                pos += 1
            if pos >= n:
                raise CliError('Unclosed index bracket, missing closing ].')
            idx_str = s[start:pos]
            pos += 1
            dup = parse_bracket_int(idx_str)
        return _make_one(name, dup)

    while pos < n:
        first = parse_one_opt()
        if pos < n and s[pos] == '-':
            pos += 1
            second = parse_one_opt()
            selectors.append(Selector('range', start=first, end=second))
        else:
            if first is None:
                first = _make_one('', None)
            selectors.append(Selector('one', one=first))
        if pos >= n:
            break
        if s[pos] == ',':
            pos += 1
            if pos >= n:
                break
            continue
        else:
            raise CliError(f"Expected end of field but got '{s[pos]}' instead.")
    return SelectColumns(selectors, invert)

def resolve_one(one, headers, no_headers):
    if one.kind == 'index':
        idx = one.index
        if idx < 1 or idx > len(headers):
            raise CliError(f"Selector index {idx} is out of bounds. Index must be >= 1 and <= {len(headers)}.")
        return idx - 1
    else:
        name = one.name
        if no_headers:
            raise CliError(f"Cannot use names ('{name}') in selection with --no-headers set.")
        name_b = _enc(name)
        matches = [i for i, h in enumerate(headers) if h == name_b]
        if not matches:
            # fallback: lossy comparison for invalid-utf8 headers
            try:
                matches = [i for i, h in enumerate(headers) if h.decode('utf-8', 'replace') == name]
            except Exception:
                matches = []
        if not matches:
            raise CliError(f"Selector name '{name}' does not exist as a named header in the given CSV data.")
        if one.dup >= len(matches):
            raise CliError(f"Selector index '{one.dup}' for name '{name}' is out of bounds. Must be >= 0 and <= {len(matches)-1}.")
        return matches[one.dup]

def resolve_selection(sel, headers, no_headers):
    """sel: SelectColumns or None. Returns list of column indices."""
    if sel is None:
        return list(range(len(headers)))
    indices = []
    for s in sel.selectors:
        if s.kind == 'one':
            indices.append(resolve_one(s.one, headers, no_headers))
        else:
            if s.start is None:
                start_idx = 0
            else:
                start_idx = resolve_one(s.start, headers, no_headers)
            if s.end is None:
                end_idx = len(headers) - 1
            else:
                end_idx = resolve_one(s.end, headers, no_headers)
            if len(headers) == 0:
                continue
            if end_idx >= start_idx:
                indices.extend(range(start_idx, end_idx + 1))
            else:
                indices.extend(range(start_idx, end_idx - 1, -1))
    if not sel.selectors:
        indices = list(range(len(headers)))
    if sel.invert:
        excluded = set(indices)
        indices = [i for i in range(len(headers)) if i not in excluded]
    return indices

# ------------------------- Docopt-like parsing -------------------------

class OptSpec:
    __slots__ = ("short", "long", "has_value", "default", "kind", "display")
    def __init__(self, short, long, has_value=False, default=None, kind='string', display=None):
        self.short = short
        self.long = long
        self.has_value = has_value
        self.default = default
        self.kind = kind
        self.display = display if display is not None else ('--' + long if long else '-' + (short or ''))
    @property
    def key(self):
        return self.long.replace('-', '_') if self.long else self.short

class CmdSpec:
    def __init__(self, name, options, pos_min, pos_max, pos_names=None, pos_kinds=None, literals=None, help_alt=False, decode_order=None):
        self.name = name
        self.options = options
        self.pos_min = pos_min
        self.pos_max = pos_max  # None = unlimited
        self.pos_names = pos_names or []
        # pos_kinds: list parallel-ish for numeric/select positionals: dict index->(kind, display)
        self.pos_kinds = pos_kinds or {}
        self.literals = literals  # for cat: first positional must be in set
        self.help_alt = help_alt
        self.decode_order = decode_order or []
        # maps
        self.by_long = {}
        self.by_short = {}
        for o in options:
            if o.long:
                self.by_long[o.long] = o
            if o.short:
                self.by_short[o.short] = o

def usage_segment(help_text):
    # Extract "Usage:\n..." up to blank line
    idx = help_text.find("Usage:\n")
    if idx == -1:
        return help_text
    rest = help_text[idx:]
    end = rest.find("\n\n")
    if end == -1:
        seg = rest.rstrip("\n")
    else:
        seg = rest[:end]
    return seg + "\n"

def parse_single_ascii(s):
    if s == "\\t":
        return 9
    b = _enc(s)
    if len(b) == 1 and b[0] < 128:
        return b[0]
    raise CliError(f"Could not convert '{s}' to a single ASCII character.")

def parse_u64_docopt(s, display):
    if s == "":
        return 0
    v = parse_rust_usize(s)
    if v is None:
        raise CliError(f"Could not deserialize '{s}' to u64 for '{display}'.")
    return v

