# ------------------------- Input sources -------------------------

_stdin_state = {'data': None, 'consumed': False}

def read_stdin_once():
    if _stdin_state['consumed']:
        return b''
    if _stdin_state['data'] is None:
        try:
            _stdin_state['data'] = sys.stdin.buffer.read()
        except OSError as e:
            raise CliError(io_error_str(e))
    _stdin_state['consumed'] = True
    return _stdin_state['data']

class InputSource:
    """Lazy input: file opened at construction, read on first load()."""
    def __init__(self, path, style='failed'):
        # style 'failed' => "failed to open {path}: ..." on open errors (except dir read)
        # style 'plain' => plain io error
        self.path = path  # None or '-' means stdin
        self.style = style
        self.fd = None
        self._data = None
        self.is_stdin = (path is None or path == '-')
        if not self.is_stdin:
            try:
                self.fd = os.open(path, os.O_RDONLY)
            except OSError as e:
                if style == 'failed':
                    raise CliError(f"failed to open {path}: {io_error_str(e)}")
                else:
                    raise CliError(io_error_str(e))
    def load(self):
        if self._data is not None:
            return self._data
        if self.is_stdin:
            self._data = read_stdin_once()
            return self._data
        chunks = []
        try:
            while True:
                chunk = os.read(self.fd, 65536)
                if not chunk:
                    break
                chunks.append(chunk)
        except OSError as e:
            raise CliError(io_error_str(e))
        finally:
            try:
                if self.fd is not None:
                    os.close(self.fd)
            except OSError:
                pass
            self.fd = None
        self._data = b''.join(chunks)
        return self._data
    def try_load_dir_check(self):
        # for directory, load() will raise Is a directory
        return self.load()

def open_input_source(path, style='failed'):
    return InputSource(path, style)

# Output handling
class OutputSink:
    def __init__(self, path):
        self.path = path
        self.is_stdout = (path is None or path == '-')
        self.f = None
        if not self.is_stdout:
            try:
                self.f = open(path, 'wb')
            except OSError as e:
                raise CliError(io_error_str(e))
    def write(self, b):
        if self.is_stdout:
            try:
                sys.stdout.buffer.write(b)
            except BrokenPipeError:
                raise CliError("Broken pipe (os error 32)")
            except OSError as e:
                raise CliError(io_error_str(e))
        else:
            try:
                self.f.write(b)
            except OSError as e:
                raise CliError(io_error_str(e))
    def flush(self):
        try:
            if self.is_stdout:
                sys.stdout.buffer.flush()
            elif self.f:
                self.f.flush()
        except BrokenPipeError:
            raise CliError("Broken pipe (os error 32)")
        except OSError as e:
            raise CliError(io_error_str(e))
    def close(self):
        if self.f:
            try:
                self.f.close()
            except OSError:
                pass
            self.f = None

def open_output(path):
    return OutputSink(path)

# ------------------------- CSV reader -------------------------

class CsvError(CliError):
    pass

class CsvReader:
    def __init__(self, source, delimiter=44, quote=34, escape=None, double_quote=True, quoting=True, flexible=False, start_offset=0, start_record_index=0):
        # source: InputSource or bytes
        self.source = source
        self.delimiter = delimiter
        self.quote = quote
        self.escape = escape
        self.double_quote = double_quote
        self.quoting = quoting
        self.flexible = flexible
        self._data = None
        self.i = start_offset
        self._line_for_i = 1  # 1 + count of \n in data[:i]; computed on load if start_offset>0
        self.record_index = start_record_index
        self.expected_len = None
        self._headers = None
        self._headers_read = False
        self._pos_byte_of_last = 0
        self._pos_of_current = (0, 1, 0)  # byte, line, record for last returned record
    def _load(self):
        if self._data is None:
            if isinstance(self.source, (bytes, bytearray)):
                self._data = bytes(self.source)
            else:
                self._data = self.source.load()
