class CsvWriter:
    def __init__(self, sink, delimiter=44, quote=34, escape=None, double_quote=True, quote_always=False, terminator=b'\n', flexible=False):
        self.sink = sink
        self.delimiter = delimiter
        self.quote = quote
        self.escape = escape
        # if escape is not None, original sets double_quote False for writer
        self.double_quote = double_quote
        self.quote_always = quote_always
        self.terminator = terminator
        self.flexible = flexible
        self.expected_len = None
        self.first = True
    def _needs_quote(self, field):
        if self.quote_always:
            return True
        d = self.delimiter
        q = self.quote
        if d in field:
            return True
        if q in field:
            return True
        if self.escape is not None and self.escape in field:
            return True
        # terminator logic
        if self.terminator == b'\n' or self.terminator == b'\r\n':
            if b'\n' in field or b'\r' in field:
                return True
        else:
            # terminator is single byte (or bytes); quote if any terminator byte present
            for b in self.terminator:
                if b in field:
                    return True
        return False
    def _write_field(self, out, field):
        if self._needs_quote(field):
            out.append(self.quote)
            if self.escape is not None:
                # escape quote chars with escape char; do not escape escape itself
                for ch in field:
                    if ch == self.quote:
                        out.append(self.escape)
                        out.append(ch)
                    else:
                        out.append(ch)
            else:
                q = self.quote
                for ch in field:
                    if ch == q:
                        out.append(q)
                        out.append(q)
                    else:
                        out.append(ch)
            out.append(self.quote)
        else:
            out.extend(field)
    def write_record(self, fields):
        # fields: iterable of bytes
        fields = list(fields)
        count = len(fields)
        out = bytearray()
        if count == 0:
            # special empty record -> ""
            out.append(self.quote)
            out.append(self.quote)
            effective_count = 0
        else:
            for idx, f in enumerate(fields):
                if idx > 0:
                    out.append(self.delimiter)
                # single empty field special-cased below via needs: if record has one empty field, must quote
                if count == 1 and len(f) == 0:
                    out.append(self.quote)
                    out.append(self.quote)
                else:
                    self._write_field(out, f)
            effective_count = count
        if self.expected_len is None:
            self.expected_len = effective_count
            self.sink.write(bytes(out) + self.terminator)
        elif not self.flexible and effective_count != self.expected_len:
            # write fields without terminator then error (mirrors csv writer)
            self.sink.write(bytes(out))
            # flush sink so partial output is visible
            try:
                self.sink.flush()
            except Exception:
                pass
            raise CsvError(f"CSV error: found record with {effective_count} fields, but the previous record has {self.expected_len} fields")
        else:
            self.sink.write(bytes(out) + self.terminator)
    def flush(self):
        self.sink.flush()

