def fmt_f64(x):
    if isinstance(x, int):
        x = float(x)
    if math.isnan(x):
        return "NaN"
    if math.isinf(x):
        return "inf" if x > 0 else "-inf"
    if x == 0.0:
        # preserve sign of -0.0
        return "-0" if math.copysign(1.0, x) < 0 else "0"
    r = repr(x)  # python shortest
    # Convert scientific / .0 notation to Rust Display (never exponent)
    try:
        d = Decimal(r)
    except InvalidOperation:
        return r
    s = format(d, 'f')
    if '.' in s:
        # strip trailing zeros? Python repr already minimal, but Decimal from '1e20' has no dot.
        # For '2.0' -> '2.0' need strip to '2'
        if s.endswith('.0'):
            s = s[:-2]
    return s

def fmt_i64_wrapping(v):
    # wrap to signed 64
    v = v & ((1 << 64) - 1)
    if v >= (1 << 63):
        v -= (1 << 64)
    return str(v)

