def translate_rust_regex(pattern):
    """Translate pattern string to python pattern string and return (pat, is_bytes_mode_global)."""
    # Determine if pattern is globally (?-u) at start (possibly with other flags)
    is_bytes = False
    # Process char by char
    out = []
    i = 0
    n = len(pattern)
    in_class = False
    while i < n:
        c = pattern[i]
        if not in_class and c == '[':
            in_class = True
            out.append(c); i += 1; continue
        if in_class and c == ']':
            # check first position literal handled by python similarly
            in_class = False
            out.append(c); i += 1; continue
        # POSIX class inside class
        if in_class and pattern.startswith('[:', i):
            end = pattern.find(':]', i+2)
            if end != -1:
                name = pattern[i+2:end]
                neg = False
                if name.startswith('^'):
                    neg = True
                    name = name[1:]
                if name in POSIX_CLASSES and not neg:
                    out.append(POSIX_CLASSES[name])
                    i = end + 2
                    continue
                # unknown posix -> treat as nested class chars in python (keep as is without brackets?) Keep original; python will treat [: as chars
            out.append(c); i += 1; continue
        if c == '\\' and i + 1 < n:
            nxt = pattern[i+1]
            if nxt in 'pP':
                neg = (nxt == 'P')
                prop = None
                adv = None
                if i + 2 < n and pattern[i+2] == '{':
                    end = pattern.find('}', i+3)
                    if end != -1:
                        prop_raw = pattern[i+3:end]
                        prop = prop_raw.split('=')[-1]
                        adv = end + 1
                elif i + 2 < n:
                    prop = pattern[i+2]
                    adv = i + 3
                if prop is not None:
                    ranges = _unicode_property_ranges(prop)
                    if ranges is None:
                        # already validated
                        out.append(pattern[i:adv]); i = adv; continue
                    content = _ranges_to_class_content(ranges)
                    if in_class:
                        if neg:
                            # Can't easily negate inside class; approximate by... for search existence rarely used. Insert content (wrong for neg)
                            # We'll fallback to a negated class as a nested? Python doesn't support. Keep content.
                            out.append(content)
                        else:
                            out.append(content)
                    else:
                        if neg:
                            out.append('[^' + content + ']')
                        else:
                            out.append('[' + content + ']')
                    i = adv; continue
            if nxt == 'x' and i + 2 < n and pattern[i+2] == '{':
                end = pattern.find('}', i+3)
                if end != -1:
                    try:
                        v = int(pattern[i+3:end], 16)
                        ch = chr(v)
                        out.append(re.escape(ch))
                        i = end + 1; continue
                    except Exception:
                        pass
            if nxt == 'u' and i + 2 < n and pattern[i+2] == '{':
                end = pattern.find('}', i+3)
                if end != -1:
                    try:
                        v = int(pattern[i+3:end], 16)
                        out.append(re.escape(chr(v)))
                        i = end + 1; continue
                    except Exception:
                        pass
            if nxt == 'z':
                out.append('\\Z'); i += 2; continue
            # default keep escape
            out.append(pattern[i:i+2]); i += 2; continue
        if not in_class and c == '(' and i + 1 < n and pattern[i+1] == '?':
            # parse flags group
            # find closing ')' or ':' for flag group
            j = i + 2
            # forms: (?P<name>...), (?P=name) (unsupported etc), (?flags), (?flags:...), (?flags-flags:...), (?:...)
            if j < n and pattern[j] == 'P':
                out.append(c); i += 1; continue
            # collect flag chars until ')' or ':'
            k = j
            while k < n and (pattern[k].isalpha() or pattern[k] == '-' or pattern[k] == '<'):
                # '<' would be lookbehind/named unsupported already
                k += 1
            if k < n and pattern[k] in '):':
                flagpart = pattern[j:k]
                # split +/- 
                if '-' in flagpart:
                    on, off = flagpart.split('-', 1)
                else:
                    on, off = flagpart, ''
                if 'u' in off:
                    # byte mode marker; if this group is at start and is global (?-u) then bytes mode
                    if i == 0 and pattern[k] == ')':
