                continue
            out.append(c); i += 1; continue
        out.append(c); i += 1
    return ''.join(out), is_bytes

class RustRegex:
    def __init__(self, pattern, ignore_case=False):
        self.pattern = pattern
        err = _detect_rust_regex_errors(pattern)
        if err is not None:
            raise err
        translated, is_bytes = translate_rust_regex(pattern)
        self.is_bytes = is_bytes
        flags = 0
        if ignore_case:
            flags |= re.IGNORECASE
        try:
            if is_bytes:
                bpat = translated.encode('utf-8')
                self.re_bytes = re.compile(bpat, flags)
                self.re = None
            else:
                self.re = re.compile(translated, flags)
                self.re_bytes = None
        except re.error as e:
            # Map python error to Rust style roughly
            msg = e.msg if hasattr(e, 'msg') else str(e)
            pos = e.pos if hasattr(e, 'pos') and e.pos is not None else 0
            # Heuristic messages
            rust_msg = msg
            # Common translations
            if 'unterminated character set' in msg or 'unterminated' in msg and '[' in pattern:
                rust_msg = 'unclosed character class'
            elif 'missing' in msg and ')' in msg:
                rust_msg = 'unclosed group'
            elif 'bad character range' in msg:
                rust_msg = 'invalid character class range, the start must be <= the end'
            elif 'nothing to repeat' in msg:
                rust_msg = 'repetition operator missing expression'
            raise CliError(_format_regex_error(pattern, min(pos, len(pattern)), 1, rust_msg))
        except Exception as e:
            raise CliError(_format_regex_error(pattern, 0, 1, str(e)))
    def is_match(self, field_bytes):
        if self.is_bytes:
            return self.re_bytes.search(field_bytes) is not None
        # decode with surrogateescape to preserve bytes
        s = field_bytes.decode('utf-8', 'surrogateescape')
        return self.re.search(s) is not None

# search
def cmd_search(values, pos, raw):
    pattern = raw[0]
    inp = raw[1] if len(raw) > 1 else None
    no_headers = values.get('no_headers', False)
    ignore_case = values.get('ignore_case', False)
    invert = values.get('invert_match', False)
    # Regex compiled before reader/writer (observed)
    regex = RustRegex(pattern, ignore_case=ignore_case)
    cdata, _ = make_reader(inp, values, no_headers=no_headers)
    wtr, sink = make_writer(values.get('output'))
    headers = cdata.headers()
    if not no_headers:
        wtr.write_record(headers)
    sel = values.get('select')
    indices = resolve_selection(sel, headers, no_headers) if sel is not None else list(range(len(headers)))
    # If file empty, indices empty etc; original with select name on empty would error during resolve above
    for rec in cdata.data_records():
        matched = False
        for idx in indices:
            if idx < len(rec) and regex.is_match(rec[idx]):
                matched = True
                break
        if invert:
            matched = not matched
        if matched:
            wtr.write_record(rec)
    wtr.flush(); sink.close()

