def cmd_search(values, pos, raw):
    pattern = raw[0]
    inp = raw[1] if len(raw) > 1 else None
    no_headers = values.get('no_headers', False)
    ignore_case = values.get('ignore_case', False)
    invert = values.get('invert_match', False)
    # Regex compiled before reader/writer (observed)
    regex = RustRegex(pattern, ignore_case=ignore_case)
    cdata, _ = make_reader(inp, values, no_headers=no_headers)
    wtr, sink = make_writer(values.get('output'))
    headers = cdata.headers()
    if not no_headers:
        wtr.write_record(headers)
    sel = values.get('select')
    indices = resolve_selection(sel, headers, no_headers) if sel is not None else list(range(len(headers)))
    # If file empty, indices empty etc; original with select name on empty would error during resolve above
    for rec in cdata.data_records():
        matched = False
        for idx in indices:
            if idx < len(rec) and regex.is_match(rec[idx]):
                matched = True
                break
        if invert:
            matched = not matched
        if matched:
            wtr.write_record(rec)
    wtr.flush(); sink.close()

