import subprocess, math, random, statistics
def ref(vals):
    inp="x\n"+"\n".join(repr(v) for v in vals)+"\n"
    p=subprocess.run(["./executable","stats"],input=inp.encode(),stdout=subprocess.PIPE)
    line=p.stdout.decode().splitlines()[1]
    parts=line.split(',')
    # field,type,sum,min,max,min_length,max_length,mean,stddev
    return float(parts[7]), float(parts[8]), parts[7], parts[8]

def welford(vals):
    n=0; mean=0.0; M2=0.0
    for x in vals:
        n+=1; delta=x-mean; mean+=delta/n; M2+=delta*(x-mean)
    return mean, math.sqrt(M2/n)
def naive(vals):
    n=len(vals); s=sum(vals); mean=s/n; var=sum(x*x for x in vals)/n-mean*mean
    return mean, math.sqrt(var) if var>0 else 0.0
def online_var(vals):
    # stats crate maybe: mean and variance maintained as running population var
    n=0; mean=0.0; var=0.0
    for x in vals:
        n+=1
        if n==1:
            mean=x; var=0.0
        else:
            old=mean
            mean += (x-mean)/n
            var += ((x-old)*(x-mean)-var)/n
    return mean, math.sqrt(var) if var>0 else 0.0
def two_pass(vals):
    mean=sum(vals)/len(vals)
    var=sum((x-mean)**2 for x in vals)/len(vals)
    return mean, math.sqrt(var)

