    return parts[7],parts[8]
def fmt(x):
    # use Rust-ish repr conversion: python repr but strip .0
    r=repr(x)
    return r[:-2] if r.endswith('.0') else r

def make_variant(name):
    def f(vals):
        n=0; mean=0.0; M2=0.0; var=0.0
        for x in vals:
            n+=1
            if name=='A':
                d=x-mean; mean+=d/n; M2+=d*(x-mean)
            elif name=='B':
                d=x-mean; mean+=d/n; M2+=d*d*(n-1)/n
            elif name=='B2':
                d=x-mean; mean+=d/n; M2+=(d*d)*((n-1)/n)
            elif name=='B3':
                d=x-mean; mean+=d/n; M2+=((n-1)*d*d)/n
            elif name=='C':
                d=x-mean; mean+=d*(1.0/n); M2+=d*(x-mean)
            elif name=='D':
                # var as population variance running
                if n==1:
                    mean=x; var=0.0; M2=0.0; continue
                d=x-mean; mean+=d/n; var+= (d*(x-mean)-var)/n; M2=var*n
            elif name=='E':
                # Youngs & Cramer? update sum squares: T += 1/(n*(n-1))*(n*x - sum_before)^2 ??? need sum
                d=x-mean; mean+=d/n; M2+=d*(x-mean)  # placeholder
            elif name=='F':
                # mean update using (old*(n-1)+x)/n
                old=mean; mean=(old*(n-1)+x)/n; d=x-old; M2+=d*(x-mean)
            elif name=='G':
                d=x-mean; mean+=d/n; d2=x-mean; M2+=d*d2
            elif name=='H':
                # delta/n added but M2 using delta^2 - (delta^2/n) : d*(x-mean) algebraically = d*d -d*d/n
                d=x-mean; mean+=d/n; M2+=d*d - d*d/n
            elif name=='I':
                d=x-mean; mean+=d/n; M2+= (x-mean)*(x-mean) * (n/(n-1)) if n>1 else 0 # wrong
        varpop=M2/n if n else 0
        return mean, math.sqrt(varpop) if varpop>0 else 0.0
    return f

