        headers = cdata.headers()
        sel = values.get('select')
        s_indices = resolve_selection(sel, headers, no_headers) if sel is not None else list(range(len(headers)))
        uniq_sorted = sorted(set(s_indices))
        tables = [dict() for _ in uniq_sorted]  # value->count preserving insertion order
        for rec in cdata.data_records():
            for tj, idx in enumerate(uniq_sorted):
                field = rec[idx] if idx < len(rec) else b''
                if no_nulls and field == b'':
                    continue
                tab = tables[tj]
                tab[field] = tab.get(field, 0) + 1
        wtr.write_record([b'field', b'value', b'count'])
        for tj, tab in enumerate(tables):
            if no_headers:
                label = str(tj + 1).encode()
            else:
                label_idx = s_indices[tj]
                label = headers[label_idx]
            items = list(tab.items())  # (value,count) insertion order
            # stable sort by count
            items_sorted = sorted(items, key=lambda kv: kv[1], reverse=not asc)
            if limit != 0:
                items_sorted = items_sorted[:limit]
            for val, cnt in items_sorted:
                out_val = b'(NULL)' if val == b'' else val
                wtr.write_record([label, out_val, str(cnt).encode()])
        wtr.flush()
    finally:
        sink.close()

