def classify_value(field):
    """Return (type_name, int_val_or_None, float_val_or_None, str_lossy)
    type_name in NULL,Integer,Float,Unicode,Unknown"""
    if len(field) == 0:
        return ('NULL', None, None, '')
    try:
        s = field.decode('utf-8')
    except UnicodeDecodeError:
        return ('Unknown', None, None, field.decode('utf-8', 'replace'))
    # Integer i64?
