    # Rust i64 parse
    t = s
    neg = False
    tt = t
    if tt.startswith('+') or tt.startswith('-'):
        tt_body = tt[1:]
    else:
        tt_body = tt
    if tt_body != '' and tt_body.isascii() and tt_body.isdigit():
