            if -9223372036854775808 <= v <= 9223372036854775807:
                iv = v
        except ValueError:
            iv = None
    if iv is not None:
        return ('Integer', iv, float(iv), s)
    fv = parse_rust_f64(s)
    if fv is not None:
        return ('Float', None, fv, s)
    return ('Unicode', None, None, s)

def parse_rust_f64(s):
    # Reject underscores, spaces
    if s == '' or '_' in s:
        return None
    if s != s.strip():
        return None
    # Rust grammar: sign? ( 'inf' | 'infinity' | 'nan' case-insensitive | Number )
    low = s.lower()
    # handle signed specials
    core = low
    sign = 1.0
    if core.startswith('+'):
        core = core[1:]
    elif core.startswith('-'):
        core = core[1:]
        sign = -1.0
    if core in ('inf', 'infinity'):
        return math.copysign(math.inf, sign)
    if core == 'nan':
        return math.nan
    # Number: digits with optional fraction/exponent, or . digits
    # Use regex
    if not re.fullmatch(r'[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?', s):
        return None
    try:
        return float(s)
    except ValueError:
