    headers2 = cdata2.headers()
    sel1 = resolve_selection(cols1, headers1, no_headers)
    sel2 = resolve_selection(cols2, headers2, no_headers)
    if len(sel1) != len(sel2):
        raise CliError(f"Column selections must have the same number of columns, but found column selections with {len(sel1)} and {len(sel2)} columns.")
    rows1 = list(cdata1.data_records())
    rows2 = list(cdata2.data_records())
    ops = []
    if values.get('left'): ops.append('left')
    if values.get('right'): ops.append('right')
    if values.get('full'): ops.append('full')
    if values.get('cross'): ops.append('cross')
    if len(ops) > 1:
        raise CliError("Please pick exactly one join operation.")
    op = ops[0] if ops else 'inner'
    wtr, sink = make_writer(values.get('output'))
    try:
        if not no_headers:
            wtr.write_record(list(headers1) + list(headers2))
        width1 = len(headers1)
        width2 = len(headers2)
        empty1 = [b''] * width1
        empty2 = [b''] * width2
        if op == 'cross':
            for r1 in rows1:
                for r2 in rows2:
                    wtr.write_record(list(r1) + list(r2))
        elif op in ('inner', 'left', 'full'):
            # index rows2
            index = {}
            for j, r2 in enumerate(rows2):
                k = _join_key(r2, sel2, no_case, nulls)
                if k is None:
                    continue
                index.setdefault(k, []).append(j)
            matched2 = set()
            for r1 in rows1:
                k = _join_key(r1, sel1, no_case, nulls)
                matches = []
                if k is not None:
                    matches = index.get(k, [])
                if matches:
                    for j in matches:
                        matched2.add(j)
                        wtr.write_record(list(r1) + list(rows2[j]))
                else:
                    if op in ('left', 'full'):
                        wtr.write_record(list(r1) + empty2)
            if op == 'full':
                for j, r2 in enumerate(rows2):
                    if j not in matched2:
                        wtr.write_record(empty1 + list(r2))
        elif op == 'right':
            index = {}
            for i, r1 in enumerate(rows1):
                k = _join_key(r1, sel1, no_case, nulls)
                if k is None:
                    continue
                index.setdefault(k, []).append(i)
            for r2 in rows2:
                k = _join_key(r2, sel2, no_case, nulls)
                matches = index.get(k, []) if k is not None else []
                if matches:
                    for i in matches:
                        wtr.write_record(list(rows1[i]) + list(r2))
                else:
                    wtr.write_record(empty1 + list(r2))
        wtr.flush()
    finally:
        sink.close()

# partition / split filename helpers

def validate_filename_template(tmpl):
    if tmpl is None or tmpl.count('{}') != 1:
        raise CliError("The --filename argument must contain one '{}'.")

def sanitize_partition_value(bucket_bytes):
    s = bucket_bytes.decode('utf-8', 'replace')
    out = []
    for ch in s:
        cat = unicodedata.category(ch)
        if cat[0] in ('L', 'M') or cat in ('Nd', 'Nl', 'Pc') or ch in ('\u200c', '\u200d'):
            out.append(ch)
    return ''.join(out)

class UniqueNames:
    def __init__(self):
        self.used = set()
        self.counter = 1
    def get(self, base):
        if base == '':
            base = 'empty'
        if base not in self.used:
            self.used.add(base)
            return base
        while True:
            cand = f"{base}_{self.counter}"
            self.counter += 1
            if cand not in self.used:
                self.used.add(cand)
                return cand

def create_dir_all(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as e:
        raise CliError(io_error_str(e))
    # makedirs with exist_ok on a file raises FileExistsError in py3? It does if path exists and not dir? Actually exist_ok suppress only if dir; if file, raises FileExistsError
    if not os.path.isdir(path):
        # mimic File exists
        raise CliError("File exists (os error 17)")

def cmd_partition(values, pos, raw):
    column_sel = pos[0]
    outdir = raw[1]
    inp = raw[2] if len(raw) > 2 else None
    tmpl = values.get('filename')
    validate_filename_template(tmpl)
    prefix_len = values.get('prefix_length')
    drop = values.get('drop', False)
    no_headers = values.get('no_headers', False)
    create_dir_all(outdir)
    cdata, _ = make_reader(inp, values, no_headers=no_headers)
    headers = cdata.headers()
    indices = resolve_selection(column_sel, headers, no_headers)
    if len(indices) != 1:
        raise CliError("can only partition on one column")
    pidx = indices[0]
    unique = UniqueNames()
    writers = {}  # bucket_bytes -> (CsvWriter, sink)
    try:
        for rec in cdata.data_records():
            field = rec[pidx] if pidx < len(rec) else b''
            bucket = field[:prefix_len] if prefix_len is not None else field
            if bucket not in writers:
                base = sanitize_partition_value(bucket)
                uniq = unique.get(base)
                fname = tmpl.replace('{}', uniq)
                fpath = os.path.join(outdir, fname)
                sink = open_output(fpath)
                wtr = CsvWriter(sink, delimiter=44, flexible=False)
                writers[bucket] = (wtr, sink)
                if not no_headers:
                    hdr = list(headers)
                    if drop:
                        hdr = [h for i, h in enumerate(hdr) if i != pidx]
                    wtr.write_record(hdr)
            wtr, sink = writers[bucket]
            out_rec = list(rec)
            if drop:
                out_rec = [v for i, v in enumerate(out_rec) if i != pidx]
            wtr.write_record(out_rec)
    finally:
        for wtr, sink in writers.values():
            try:
                wtr.flush()
            except Exception:
                pass
            sink.close()

def cmd_split(values, pos, raw):
    outdir = raw[0]
    inp = raw[1] if len(raw) > 1 else None
    tmpl = values.get('filename')
    validate_filename_template(tmpl)
    size = values.get('size')
    if size is None:
        size = 500
    if size == 0:
        raise CliError("--size must be greater than 0.")
    no_headers = values.get('no_headers', False)
    create_dir_all(outdir)
    cdata, indexed = make_reader(inp, values, no_headers=no_headers, use_index=True)
    # indexed check for stale done; parallel ignored
    headers = cdata.headers()
    # create first chunk
    def new_chunk(start_idx):
        fname = tmpl.replace('{}', str(start_idx))
        fpath = os.path.join(outdir, fname)
        sink = open_output(fpath)
        wtr = CsvWriter(sink, delimiter=44, flexible=False)
        if not no_headers:
            # write headers even if empty (produces "")
            wtr.write_record(list(headers))
        return wtr, sink
    wtr, sink = new_chunk(0)
    try:
        for i, rec in enumerate(cdata.data_records()):
            if i > 0 and i % size == 0:
                wtr.flush(); sink.close()
                wtr, sink = new_chunk(i)
            wtr.write_record(rec)
        wtr.flush()
    finally:
        sink.close()

# index
def cmd_index(values, pos, raw):
    inp = raw[0]
    if inp == '-':
        raise CliError("Cannot use <stdin> here")
    out_path = values.get('output')
    if out_path is None:
        out_path = inp + ".idx"
    delim = values.get('delimiter', 44)
    # Open input fd first (plain errors)
    try:
        fd = os.open(inp, os.O_RDONLY)
    except OSError as e:
        raise CliError(io_error_str(e))
    # Create output
    try:
        out_f = open(out_path, 'wb')
    except OSError as e:
        try: os.close(fd)
        except Exception: pass
        raise CliError(io_error_str(e))
    # Now read input bytes from fd (if dir, error)
    chunks = []
    try:
        while True:
            chunk = os.read(fd, 65536)
            if not chunk:
                break
            chunks.append(chunk)
    except OSError as e:
        out_f.close()
        try: os.close(fd)
        except Exception: pass
        raise CliError(io_error_str(e))
    try: os.close(fd)
    except Exception: pass
    data = b''.join(chunks)
    reader = CsvReader(data, delimiter=delim, flexible=False)
    positions = []
    err = None
    count = 0
    try:
        while True:
            rec = reader.read_record()
            if rec is None:
                break
            pos_byte, pos_line, pos_rec = reader.position_of_last_record()
            positions.append(pos_byte)
            count += 1
    except CliError as e:
        err = e
    try:
        for p in positions:
            out_f.write(struct.pack('>Q', p))
        if err is None:
            out_f.write(struct.pack('>Q', count))
        out_f.flush()
    finally:
        out_f.close()
    if err is not None:
        raise err

