def main(argv):
    # argv excludes program name
    # Main parsing with options_first-ish behavior
    args = argv
    # Find command token using our main parser
    # State
    flags = {'help': 0, 'list': 0, 'version': 0}
    positionals = []
    rest = []
    i = 0
    end_opts = False
    # helpers for usage errors
    def usage_err(msg):
        raise UsageError(msg, MAIN_USAGE_SEGMENT)
    while i < len(args):
        tok = args[i]
        if positionals:
            break
        if not end_opts and tok == '--':
            end_opts = True
            i += 1
            continue
        if not end_opts and tok.startswith('--') and tok != '--':
            if '=' in tok:
                name, eqval = tok.split('=', 1)
                has_eq = True
            else:
                name, eqval = tok, None
                has_eq = False
            lname = name[2:]
            known = {'help': 'help', 'list': 'list', 'version': 'version'}
            if lname not in known:
                cand_list = ['--list', '--help', '--version']
                best = None; bestdist = 3
                for cand in cand_list:
                    d = levenshtein(name, cand)
                    if d < bestdist:
                        bestdist = d; best = cand
                if best is not None:
                    usage_err(f"Unknown flag: '{name}'. Did you mean '{best}'?")
                else:
                    usage_err(f"Unknown flag: '{name}'")
            if has_eq:
                usage_err(f"Flag '--{lname}' cannot have an argument, but found '{eqval}'.")
            flags[known[lname]] += 1
            i += 1
            continue
        elif not end_opts and tok.startswith('-') and tok != '-':
            chars = tok[1:]
            for c in chars:
                if c == 'h':
                    flags['help'] += 1
                else:
                    usage_err(f"Unknown flag: '-{c}'")
            i += 1
            continue
        else:
            positionals.append(tok)
            rest = args[i+1:]
            break
    # duplicate check
    dup = any(v > 1 for v in flags.values())
    if positionals:
        if dup or any(flags.values()):
            raise UsageError("Invalid arguments.", MAIN_USAGE_SEGMENT)
        cmd_token = positionals[0]
        lowered = rust_lower(cmd_token)
        if lowered not in VARIANT_COMMANDS:
            raise CliError(f"Could not match '{lowered}' with any of the allowed variants: {VARIANT_COMMANDS}".replace("'", '"') if False else f"Could not match '{lowered}' with any of the allowed variants: [\"cat\", \"count\", \"fixlengths\", \"flatten\", \"fmt\", \"frequency\", \"headers\", \"help\", \"index\", \"input\", \"join\", \"partition\", \"reverse\", \"sample\", \"search\", \"select\", \"slice\", \"sort\", \"split\", \"stats\", \"table\"]")
        # lowercase expectation check: argv[0] (first arg overall) must equal lowered
        first_arg = args[0] if args else ''
        if first_arg != lowered:
            raise CliError(f"xsv expects commands in lowercase. Did you mean '{rust_lower(first_arg)}'?")
        if lowered == 'help':
            out_bytes(_enc(MAIN_RAW))
            return 0
        spec = SPECS[lowered]
        values, pos_values, raw_pos = docopt_parse(spec, rest)
        func = COMMAND_FUNCS[lowered]
        func(values, pos_values, raw_pos)
        return 0
    else:
        if dup:
            raise UsageError("Invalid arguments.", MAIN_USAGE_SEGMENT)
        if flags['help']:
            out_bytes(_enc(MAIN_HELP))
            return 0
        if flags['version']:
            out_bytes(b"0.13.0\n")
            return 0
        if flags['list']:
            out_bytes(_enc(LIST_OUT))
            return 0
        # no args (or just --)
        err_bytes(_enc(NOARGS_OUT))
        return 0

def _entry():
    try:
        rc = main(sys.argv[1:])
        try:
            sys.stdout.buffer.flush()
        except Exception:
            pass
        sys.exit(rc if isinstance(rc, int) else 0)
    except HelpExit as e:
        out_bytes(_enc(e.text))
        try: sys.stdout.buffer.flush()
        except Exception: pass
        sys.exit(0)
    except UsageError as e:
        try:
            sys.stdout.buffer.flush()
        except Exception:
            pass
        err_bytes(_enc(e.msg + "\n\n" + e.usage))
        sys.exit(1)
    except CliError as e:
        try:
            sys.stdout.buffer.flush()
        except Exception:
            pass
        # CliError msg may already contain trailing newline? Our messages don't.
        err_bytes(_enc(e.msg + "\n"))
        sys.exit(1)
    except BrokenPipeError:
        # Rust would ... try quiet
        try:
            sys.stderr.buffer.write(b"Broken pipe (os error 32)\n")
        except Exception:
            pass
        sys.exit(1)

if __name__ == '__main__':
    _entry()
