def rotl(x,r): return ((x<<r)&MASK32)|(x>>(32-r)) if r else x
class HC128:
    def __init__(self,key_bytes,iv_bytes):
        W=[0]*1280
        def word(b,o): return int.from_bytes(b[o:o+4],'little')
        for i in range(8): W[i]=word(key_bytes,(i%4)*4)
        for i in range(8,16): W[i]=word(iv_bytes,((i-8)%4)*4)
        def f1(x): return rotr(x,7)^rotr(x,18)^(x>>3)
        def f2(x): return rotr(x,17)^rotr(x,19)^(x>>10)
        for i in range(16,1280):
            W[i]=(f2(W[i-2])+W[i-7]+f1(W[i-15])+W[i-16]+i)&MASK32
        self.P=W[256:768];self.Q=W[768:1280];self.cnt=0
