    def g1(self,x,y): return ((rotr(x,10)^rotr(y,23))+rotr(x,8))&MASK32
    def g2(self,x,y): return ((rotl(x,10)^rotl(y,23))+rotl(x,8))&MASK32
    def h1(self,x): return (self.Q[x&0xff]+self.Q[256+((x>>16)&0xff)])&MASK32
    def h2(self,x): return (self.P[x&0xff]+self.P[256+((x>>16)&0xff)])&MASK32
    def step(self):
        j=self.cnt&511
        if self.cnt<512:
            x=self.P[(j-3)&511]
            self.P[j]=(self.P[j]+self.P[(j-10)&511]+self.g1(x,self.Q[x&511]))&MASK32
            out=self.h1(self.P[j])^self.P[j]
