            x=self.Q[(j-3)&511]
            self.Q[j]=(self.Q[j]+self.Q[(j-10)&511]+self.g2(x,self.P[x&511]))&MASK32
            out=self.h2(self.Q[j])^self.Q[j]
        self.cnt=(self.cnt+1)&1023
        return out&MASK32

def hc_u32_stream(key,iv):
    h=HC128(key,iv)
    while True:yield h.step()
