        for i in range(n):
            if i<k:res.append(i)
            else:
                j=rng.gen_range(i+1)
                if j<k:res[j]=i
        return res
    if algo=='R_drawall':
        res=[]
        for i in range(n):
            j=rng.gen_range(i+1)
            if i<k:res.append(i)
            elif j<k:res[j]=i
        return res
    if algo=='R_prob':
